            --surface-color: #1e1e1e;
            --text-color: #e0e0e0;
            --text-muted: #9e9e9e;
            --border-color: #424242;
            --focus-color: #90caf9;
            --error-color: #ffb4ab;
            --btn-bg: #90caf9;
            --btn-text: #121212;
            --btn-hover: #bbdefb;
            --success-bg: #1e4620;
            --success-border: #2e7d32;
            --success-text: #e8f5e9;
        }

