    <script crossorigin src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
</head>
<body>
    <main>
        <h1>Contact Support</h1>
        <div id="root"></div>
    </main>
    <script type="text/babel">
        const { useState, useRef } = React;

        function ContactForm() {
            const [formData, setFormData] = useState({
                fullName: '',
                email: '',
                phone: ''
            });
            const [errors, setErrors] = useState({});
            const [touched, setTouched] = useState({});
            const [isSubmitting, setIsSubmitting] = useState(false);
            const [submitSuccess, setSubmitSuccess] = useState(false);

            const fullNameRef = useRef(null);
            const emailRef = useRef(null);
            const phoneRef = useRef(null);

            const validate = (name, value) => {
                switch(name) {
                    case 'fullName':
                        return value.trim() ? '' : 'Full name is required.';
                    case 'email':
                        if (!value.trim()) return 'Email address is required.';
                        // Basic email validation regex
                        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return 'Enter a valid email address.';
                        return '';
                    case 'phone':
                        // Optional field, only validate if there is a value
                        if (value.trim() && !/^\d{3}-\d{3}-\d{4}$/.test(value)) {
                            return 'Phone number must be in the format: 123-456-7890.';
                        }
                        return '';
                    default:
                        return '';
                }
            };

            const handleChange = (e) => {
                const { name, value } = e.target;
                setFormData(prev => ({ ...prev, [name]: value }));
                // Validate on change if already touched
                if (touched[name]) {
                    setErrors(prev => ({ ...prev, [name]: validate(name, value) }));
                }
            };

            const handleBlur = (e) => {
                const { name, value } = e.target;
                setTouched(prev => ({ ...prev, [name]: true }));
                setErrors(prev => ({ ...prev, [name]: validate(name, value) }));
            };

            const handleSubmit = (e) => {
                e.preventDefault();

                // Validate all fields before submission
                const newErrors = {
                    fullName: validate('fullName', formData.fullName),
                    email: validate('email', formData.email),
                    phone: validate('phone', formData.phone)
                };

                setErrors(newErrors);
                setTouched({ fullName: true, email: true, phone: true });

                // Check if there are any errors
                const firstErrorField = Object.keys(newErrors).find(key => newErrors[key] !== '');

                if (firstErrorField) {
                    // Focus the first invalid field for accessibility
                    if (firstErrorField === 'fullName' && fullNameRef.current) fullNameRef.current.focus();
                    else if (firstErrorField === 'email' && emailRef.current) emailRef.current.focus();
                    else if (firstErrorField === 'phone' && phoneRef.current) phoneRef.current.focus();
                    return;
                }

                setIsSubmitting(true);
                setSubmitSuccess(false);

                // Simulate network request
                setTimeout(() => {
                    setIsSubmitting(false);
                    setSubmitSuccess(true);
                    setFormData({ fullName: '', email: '', phone: '' });
                    setTouched({});
                    setErrors({});
                }, 1000);
            };

            return (
                <form onSubmit={handleSubmit} noValidate aria-label="Support Contact Form">
                    {submitSuccess && (
                        <div className="status-message" role="status" aria-live="polite">
                            Your message has been sent successfully. We will get back to you soon.
                        </div>
                    )}

                    <div className="form-field">
                        <label htmlFor="fullName">
                            Full Name <span className="required-indicator" aria-hidden="true">*</span>
                        </label>
                        <input
                            type="text"
                            id="fullName"
                            name="fullName"
                            ref={fullNameRef}
                            value={formData.fullName}
                            onChange={handleChange}
                            onBlur={handleBlur}
                            required
                            aria-required="true"
                            aria-invalid={!!errors.fullName}
                            aria-describedby={errors.fullName ? "fullName-error" : undefined}
                            autoComplete="name"
                        />
                        {errors.fullName && (
                            <div id="fullName-error" className="error-message">
                                {errors.fullName}
                            </div>
                        )}
                    </div>

                    <div className="form-field">
                        <label htmlFor="email">
                            Email Address <span className="required-indicator" aria-hidden="true">*</span>
                        </label>
                        <input
                            type="email"
                            id="email"
                            name="email"
                            ref={emailRef}
                            value={formData.email}
                            onChange={handleChange}
                            onBlur={handleBlur}
                            required
                            aria-required="true"
                            aria-invalid={!!errors.email}
                            aria-describedby={errors.email ? "email-error" : undefined}
                            autoComplete="email"
                        />
                        {errors.email && (
                            <div id="email-error" className="error-message">
                                {errors.email}
                            </div>
                        )}
                    </div>

                    <div className="form-field">
                        <label htmlFor="phone">
                            Phone Number (Optional)
                        </label>
                        <input
                            type="tel"
                            id="phone"
                            name="phone"
                            ref={phoneRef}
                            value={formData.phone}
                            onChange={handleChange}
                            onBlur={handleBlur}
                            aria-invalid={!!errors.phone}
                            aria-describedby={`phone-helper ${errors.phone ? "phone-error" : ""}`.trim()}
                            autoComplete="tel"
                        />
                        <div id="phone-helper" className="helper-text">
                            Format: 123-456-7890
                        </div>
                        {errors.phone && (
                            <div id="phone-error" className="error-message">
                                {errors.phone}
                            </div>
                        )}
                    </div>

                    <button type="submit" disabled={isSubmitting}>
                        {isSubmitting ? 'Sending...' : 'Submit'}
                    </button>
                </form>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ContactForm />);
    </script>
</body>
